'use strict';
// V307 · A2: bật lớp CSS thanh máu/Bạo Tẩu kiểu neon (hud307b.css) + ảnh GPT B12 (khung, lấp máu, lấp Bạo Tẩu, băng cảnh báo boss). Tắt: window.HUD307B=false · chỉ tắt ảnh: window.B12307=false
(()=>{const I={khung:'data:image/webp;base64,',mau:'data:image/webp;base64,',bt:'data:image/webp;base64,',bang:'data:image/webp;base64,'};
 const st=document.createElement('style');st.id='b12307-var';st.textContent=':root{--b12-khung:url('+I.khung+');--b12-mau:url('+I.mau+');--b12-bt:url('+I.bt+');--b12-bang:url('+I.bang+')}';document.head.appendChild(st);
 function s(){const r=document.documentElement;r.classList.toggle('hud307b',window.HUD307B!==false);r.classList.toggle('b12307',window.B12307!==false);}s();setInterval(s,1500);})();
